           float norm = (inp_bt[i] - mean_bt) * rstd_bt;
           float dnorm = weight[i] * dout_bt[i];
           dnorm_mean += dnorm;
           dnorm_norm_mean += dnorm * norm;
         }
         dnorm_mean /= (float)C;
         dnorm_norm_mean /= (float)C;
         for (int i = 0; i < C; i++) {
           float norm = (inp_bt[i] - mean_bt) * rstd_bt;
           float dnorm = weight[i] * dout_bt[i];
           atomic_float_ref(dbias[i]).fetch_add(dout_bt[i]);
